"use strict";
const pptxgen = require("pptxgenjs");
const path = require("path");

// ── Color palette (Midnight Executive variant for data/tech) ──────────────────
const C = {
  darkBg:    "1A2745",   // dark navy – title & close slides
  midBg:     "213057",   // slightly lighter navy
  lightBg:   "F5F7FA",   // off-white – content slides
  white:     "FFFFFF",
  accent:    "00A3C4",   // teal accent
  accentAlt: "F4A417",   // amber accent (callouts)
  bodyText:  "1E293B",   // near-black
  mutedText: "64748B",   // slate muted
  barColor1: "00A3C4",
  barColor2: "0D6E8A",
};

// ── Helpers ───────────────────────────────────────────────────────────────────
function titleStyle(slide, text) {
  slide.addText(text, {
    x: 0.5, y: 0.28, w: 9.0, h: 0.7,
    fontSize: 26, bold: true, color: C.bodyText,
    fontFace: "Calibri", align: "left", margin: 0,
  });
}

function accentRule(slide, y = 1.05) {
  // Thin teal horizontal rule under title area on light slides
  slide.addShape("rect", {
    x: 0.5, y, w: 9.0, h: 0.04,
    fill: { color: C.accent }, line: { color: C.accent, width: 0 },
  });
}

function footerLight(slide) {
  slide.addText("2024 Stack Overflow Developer Survey  |  65,437 respondents  |  180+ countries", {
    x: 0.5, y: 5.35, w: 9.0, h: 0.22,
    fontSize: 9, color: C.mutedText, fontFace: "Calibri", align: "left", margin: 0,
  });
}

function footerDark(slide) {
  slide.addText("2024 Stack Overflow Developer Survey  |  65,437 respondents  |  180+ countries", {
    x: 0.5, y: 5.35, w: 9.0, h: 0.22,
    fontSize: 9, color: "7A9BBF", fontFace: "Calibri", align: "left", margin: 0,
  });
}

function slideNumDark(slide, n) {
  slide.addText(`${n} / 8`, {
    x: 8.5, y: 5.35, w: 1.0, h: 0.22,
    fontSize: 9, color: "7A9BBF", fontFace: "Calibri", align: "right", margin: 0,
  });
}

function slideNumLight(slide, n) {
  slide.addText(`${n} / 8`, {
    x: 8.5, y: 5.35, w: 1.0, h: 0.22,
    fontSize: 9, color: C.mutedText, fontFace: "Calibri", align: "right", margin: 0,
  });
}

// ── Presentation setup ────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author  = "StackOverflow Survey Analysis";
pres.title   = "Developer Workforce & Compensation Trends — 2024 Stack Overflow Survey";

// ═════════════════════════════════════════════════════════════════════════════
// SLIDE 1 – Title
// ═════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.darkBg };

  // Top accent bar
  s.addShape("rect", { x: 0, y: 0, w: 10, h: 0.08, fill: { color: C.accent }, line: { color: C.accent, width: 0 } });

  // Survey logo / icon block (teal rectangle)
  s.addShape("rect", { x: 0.5, y: 1.3, w: 0.08, h: 2.6, fill: { color: C.accent }, line: { color: C.accent, width: 0 } });

  // Main title
  s.addText("Developer Workforce &\nCompensation Trends", {
    x: 0.8, y: 1.3, w: 8.2, h: 1.6,
    fontSize: 38, bold: true, color: C.white,
    fontFace: "Calibri", align: "left", valign: "top",
  });

  // Subtitle
  s.addText("2024 Stack Overflow Developer Survey", {
    x: 0.8, y: 2.95, w: 8.2, h: 0.5,
    fontSize: 20, bold: false, color: C.accent,
    fontFace: "Calibri", align: "left",
  });

  // Stats row
  s.addText("65,437 respondents  ·  180+ countries  ·  34.7% salary response rate", {
    x: 0.8, y: 3.55, w: 8.2, h: 0.4,
    fontSize: 13, color: "A8C4E0", fontFace: "Calibri", align: "left",
  });

  // Bottom attribution
  s.addText("Source: stackoverflow.co/survey/2024", {
    x: 0.5, y: 5.2, w: 9.0, h: 0.3,
    fontSize: 10, color: "5A7FA0", fontFace: "Calibri", align: "left",
  });

  slideNumDark(s, 1);
}

// ═════════════════════════════════════════════════════════════════════════════
// SLIDE 2 – Employment Status
// ═════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  titleStyle(s, "84% of Developers Are Working, but Full-Time Employment Dips in the U.S.");
  accentRule(s, 1.05);

  // Two stat callout boxes
  const boxes = [
    { label: "Global Full-Time", val: "69%", sub: "Dominant employment mode", x: 0.5 },
    { label: "U.S. Full-Time 2024", val: "64.8%", sub: "Down from 69% in 2023 (−4.2pp)", x: 3.4 },
    { label: "Freelance / Contract", val: "16.4%", sub: "Global independent contractors", x: 6.3 },
  ];

  boxes.forEach(b => {
    s.addShape("rect", {
      x: b.x, y: 1.18, w: 2.7, h: 1.3,
      fill: { color: C.white },
      shadow: { type: "outer", color: "000000", blur: 8, offset: 2, angle: 135, opacity: 0.10 },
      line: { color: "E2E8F0", width: 1 },
    });
    s.addText(b.val, {
      x: b.x, y: 1.22, w: 2.7, h: 0.65,
      fontSize: 34, bold: true, color: C.accent, fontFace: "Calibri", align: "center", margin: 0,
    });
    s.addText(b.label, {
      x: b.x, y: 1.87, w: 2.7, h: 0.28,
      fontSize: 11, bold: true, color: C.bodyText, fontFace: "Calibri", align: "center", margin: 0,
    });
    s.addText(b.sub, {
      x: b.x, y: 2.15, w: 2.7, h: 0.28,
      fontSize: 9, color: C.mutedText, fontFace: "Calibri", align: "center", margin: 0,
    });
  });

  // Bar chart – Grouped: Global vs U.S. employment mode
  const chartData = [
    { name: "Global", labels: ["Full-Time", "Freelance/Contract", "Student"], values: [69, 16.4, 13.2] },
    { name: "U.S. 2024", labels: ["Full-Time", "Freelance/Contract", "Student"], values: [64.8, 16.4, 13.2] },
  ];

  s.addChart(pres.charts.BAR, chartData, {
    x: 0.5, y: 2.6, w: 9.0, h: 2.5,
    barDir: "col",
    barGrouping: "clustered",
    chartColors: [C.barColor1, C.accentAlt],
    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.mutedText,
    valAxisLabelColor: C.mutedText,
    valAxisMaxVal: 80,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelColor: C.bodyText,
    dataLabelFontSize: 9,
    legendPos: "t",
    showLegend: true,
    legendFontColor: C.mutedText,
    legendFontSize: 10,
  });

  footerLight(s);
  slideNumLight(s, 2);
}

// ═════════════════════════════════════════════════════════════════════════════
// SLIDE 3 – Work Environment
// ═════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  titleStyle(s, "In-Person Work Rises to 20% While Hybrid Holds Steady at 42%");
  accentRule(s, 1.05);

  // Three big stat cards
