{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };

  titleStyle(s, "Experience Pays: Top Roles Combine 14+ Years with Six-Figure Salaries");
  accentRule(s, 1.05);

  // Annotation callouts
  const annos = [
    { text: "Senior Exec / Dev Advocate\n$124K–$127K · ~16–17 yrs", x: 0.5, y: 1.2, col: C.accent },
    { text: "Student outlier\n$15K · ~2 yrs experience", x: 0.5, y: 2.1, col: C.accentAlt },
  ];
  annos.forEach(a => {
    s.addShape("rect", {
      x: a.x, y: a.y, w: 2.8, h: 0.65,
      fill: { color: C.white },
      line: { color: a.col, width: 1.5 },
      shadow: { type: "outer", color: "000000", blur: 4, offset: 1, angle: 135, opacity: 0.08 },
    });
    s.addText(a.text, {
      x: a.x + 0.08, y: a.y + 0.04, w: 2.64, h: 0.57,
      fontSize: 9, color: C.bodyText, fontFace: "Calibri", bold: true, align: "left", valign: "middle", margin: 0,
    });
  });

  // Main figure image (scatter plot from source)
  s.addImage({
    path: path.join(__dirname, "benchmark", "assets", "figure_2.jpg"),
    x: 3.4, y: 1.15, w: 6.2, h: 4.0,
    sizing: { type: "contain", w: 6.2, h: 4.0 },
  });

  s.addText("Reference chart: Stack Overflow Survey 2024 — Salary vs. experience by developer type", {
    x: 3.4, y: 5.1, w: 6.2, h: 0.2,
    fontSize: 8, color: C.mutedText, fontFace: "Calibri", align: "center", margin: 0,
  });

  footerLight(s);
  slideNumLight(s, 5);
}

