  // Left: company size bar chart
  const sizeLabels = ["Freelancer", "2–9", "10–19", "20–99", "100–499", "500–999", "1K–4.9K", "5K–9.9K", "10K+"];
  const sizeVals   = [6.1, 10.4, 8.9, 21.2, 18.5, 6.7, 11.0, 3.8, 11.4];

  s.addChart(pres.charts.BAR, [{
    name: "% Respondents",
    labels: sizeLabels,
    values: sizeVals,
  }], {
    x: 0.4, y: 1.2, w: 5.0, h: 3.8,
    barDir: "bar",
    chartColors: [C.barColor1],
    chartArea: { fill: { color: C.lightBg } },
    catAxisLabelColor: C.mutedText,
    catAxisLabelFontSize: 9,
    valAxisLabelColor: C.mutedText,
    valAxisLabelFontSize: 9,
    valAxisMaxVal: 25,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showValue: true,
    dataLabelColor: C.bodyText,
    dataLabelFontSize: 8,
    dataLabelFormatCode: '0.0"%"',
    showLegend: false,
    titleFontSize: 11,
    showTitle: true,
    title: "Company Size Distribution (42,827 respondents)",
    titleColor: C.mutedText,
  });

  // Right: purchasing influence callouts
  const pCards = [
    { val: "62%", label: "influence tech purchases", note: "across all respondents" },
    { val: "60%", label: "prefer build-and-buy", note: "vs. pure build or buy" },
    { val: "75%", label: "use free trials", note: "to evaluate new tools" },
    { val: "73%", label: "ask other developers", note: "for tool recommendations" },
  ];

  pCards.forEach((c, i) => {
    const row = Math.floor(i / 2);
    const col = i % 2;
    const px = 5.7 + col * 2.15;
    const py = 1.2 + row * 1.5;
    s.addShape("rect", {
      x: px, y: py, w: 2.0, h: 1.25,
      fill: { color: C.white },
      line: { color: "E2E8F0", width: 1 },
      shadow: { type: "outer", color: "000000", blur: 6, offset: 2, angle: 135, opacity: 0.09 },
    });
    // left accent stripe
    s.addShape("rect", { x: px, y: py, w: 0.07, h: 1.25, fill: { color: C.accent }, line: { color: C.accent, width: 0 } });
    s.addText(c.val, {
      x: px + 0.12, y: py + 0.08, w: 1.8, h: 0.5,
      fontSize: 26, bold: true, color: C.accent, fontFace: "Calibri", align: "left", margin: 0,
    });
    s.addText(c.label, {
      x: px + 0.12, y: py + 0.56, w: 1.8, h: 0.3,
      fontSize: 9, bold: true, color: C.bodyText, fontFace: "Calibri", align: "left", margin: 0,
    });
    s.addText(c.note, {
      x: px + 0.12, y: py + 0.85, w: 1.8, h: 0.3,
      fontSize: 8, color: C.mutedText, fontFace: "Calibri", align: "left", margin: 0,
    });
  });

  // Top-level influencer roles note
  s.addText("Top influencers: Senior Exec (99%)  ·  Eng. Manager (87%)  ·  Product Manager (77%)", {
    x: 5.7, y: 4.25, w: 4.0, h: 0.35,
    fontSize: 9, color: C.mutedText, fontFace: "Calibri", align: "left",
  });

  footerLight(s);
  slideNumLight(s, 7);
}

