  const cols = [
    [takeaways[0], takeaways[1]],
    [takeaways[2], takeaways[3]],
    [takeaways[4]],
  ];

  const colX = [0.3, 3.55, 6.8];
  const cardW = 3.0;
  const cardH = 1.6;
  const startY = 1.05;

  takeaways.forEach((t, i) => {
    const col = i < 2 ? 0 : i < 4 ? 1 : 2;
    const row = i < 2 ? i : i < 4 ? i - 2 : 0;
    const cx = colX[col];
    const cy = startY + row * (cardH + 0.18);

    s.addShape("rect", {
      x: cx, y: cy, w: cardW, h: cardH,
      fill: { color: "223060" },
      line: { color: "2E4080", width: 1 },
    });
    // Accent top stripe
    s.addShape("rect", { x: cx, y: cy, w: cardW, h: 0.05, fill: { color: C.accent }, line: { color: C.accent, width: 0 } });

    // Number badge
    s.addText(t.num, {
      x: cx + 0.1, y: cy + 0.08, w: 0.45, h: 0.38,
      fontSize: 14, bold: true, color: C.accent, fontFace: "Calibri", align: "left", margin: 0,
    });
    // Heading
    s.addText(t.head, {
      x: cx + 0.1, y: cy + 0.45, w: cardW - 0.2, h: 0.38,
      fontSize: 10, bold: true, color: C.white, fontFace: "Calibri", align: "left", margin: 0,
    });
    // Body
    s.addText(t.body, {
      x: cx + 0.1, y: cy + 0.83, w: cardW - 0.2, h: 0.7,
      fontSize: 8.5, color: "A8C4E0", fontFace: "Calibri", align: "left", valign: "top", margin: 0,
    });
  });

  footerDark(s);
  slideNumDark(s, 8);
}

